  if (!ACCOUNT_TYPES.includes(type)) {
    throw new LedgerError('UNKNOWN_TYPE', `unknown account type: ${type}`);
  }

  // Credit-normal types need negation
  if (normalSide(type) === 'credit') {
    return -signedCents;
